const { chromium } = require('@playwright/test');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 960 }, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:27063', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/tmp/mico-monsoon-screenshot.png', fullPage: true });
  await browser.close();
})();

const ops = [];
function update(id, patch) { ops.push({ type: 'update', id, patch }); }

update('s-xibei-dot', { x: 1005, y: 402 });
update('s-xibei-label', { x: 970, y: 427, w: 130, h: 28 });
