update('s-huabei-label', { x: 1100, y: 350, w: 130, h: 28 });
update('s-huanan-dot', { x: 1195, y: 420 });
update('s-huanan-label', { x: 1160, y: 442, w: 130, h: 28 });

console.log(JSON.stringify(ops));
